var maxLength = function(nums) {
    function gcd(a, b) {
        while (b !== 0) {
            const rem = a % b;
            a = b;
            b = rem;
        }
        return a;
    }

    function lcm(a, b) {
        return (a / gcd(a, b)) * b;
    }

    let best = 0;

    // g and l hold the running GCD and LCM.
    for (let i = 0; i < nums.length; i++) {
        let prod = 1;
        let g = 0;
        let l = 1;

        for (let j = i; j < nums.length; j++) {
            const num = nums[j];
            prod *= num;
            g = gcd(g, num);
            l = lcm(l, num);

            const target = g * l;

            if (prod === target) {
                best = Math.max(best, j - i + 1);
            } else if (prod > target) {
                break;
            }
        }
    }

    return best;
};
